# -*- coding: utf-8 -*-
"""MANAPRINT — L'AS DES AS · 4 boules (création 2KEA) · maquette CANVA de Maeva (26/11/2026,
« as_des_as_canva_12_A4 ») reprise TELLE QUELLE : 12 billets / feuille A4 PAYSAGE (3 colonnes x 4 rangées),
traits de coupe en pointillés. Chaque billet : pastille « N° », L'AS DES AS, le grand As penché,
4 cartes en éventail, les jetons et « TUKEA 89 22 23 05 ».
Les couleurs des cartes tournent de billet en billet comme sur la maquette :
pique · cœur · trèfle · carreau (4 dessins, chacun enregistré une seule fois par document).
RÈGLE (inchangée) — 4 numéros, un par carte, de gauche à droite :
   1re carte 1-15 · 2e 16-30 · 3e 31-45 · 4e 46-75 -> crieur 1 à 75.
Chiffres comme la maquette : écriture à empattements grasse (Times-Bold), 30 pt (le maximum),
penchés avec leur carte.
Le tout est réduit pour garder 6 mm de marge d'impression (Konica / Sharp).
(L'ancien as_des_as.py reste dans le dossier, il n'est plus appelé.)"""
import io, random
from reportlab.pdfgen import canvas
from reportlab.lib.pagesizes import landscape, A4
from reportlab.lib import colors

PAGE_W, PAGE_H = landscape(A4)
COLS, RANGS = 3, 4
CARTES_PAGE = COLS * RANGS                # 12
CELL_W, CELL_H = 280.6299, 148.8189
NOIR = colors.black
GRIS = colors.Color(.3, .3, .3)
RAINBOW = ["#E53935", "#FB8C00", "#F9A825", "#43A047", "#00ACC1",
           "#1E88E5", "#3949AB", "#8E24AA", "#D81B60", "#6D4C41"]
POLICE_NUM, T_NUM = "Times-Bold", 30
# chaque carte : sa position / son inclinaison (comme la maquette) et sa plage
CARTES = [((0.9984, 0.0558, -0.0558, 0.9984, 98.0787, 70.8661), (1, 15)),
          ((0.9998, 0.0209, -0.0209, 0.9998, 146.8346, 73.1339), (16, 30)),
          ((0.9998, -0.0209, 0.0209, 0.9998, 195.5906, 73.1339), (31, 45)),
          ((0.9984, -0.0558, 0.0558, 0.9984, 244.3465, 70.8661), (46, 75))]
CASES = [(0, 0, pl) for _m, pl in CARTES]

MARGE_SURE = 6 * 72 / 25.4
ECHELLE = min((PAGE_W - 2 * MARGE_SURE) / PAGE_W, (PAGE_H - 2 * MARGE_SURE) / PAGE_H)
DECAL_X = (PAGE_W - PAGE_W * ECHELLE) / 2.0
DECAL_Y = (PAGE_H - PAGE_H * ECHELLE) / 2.0
_DEJA = set()


def _numeros(rng):
    for _ in range(400):
        t = tuple(rng.randint(lo, hi) for _x, _y, (lo, hi) in CASES)
        if t not in _DEJA:
            break
    _DEJA.add(t)
    return t


def _txt(c, s, x, y, police, taille, col, centre=False):
    w = c.stringWidth(s, police, taille)
    t = c.beginText(x - w / 2.0 if centre else x, y); t.setFont(police, taille)
    t.setFillColor(col); t.textOut(s)
    c.drawText(t)


def _modele(c, k):
    nom = "ASDESAS_DESSIN_%d" % k
    if getattr(c, "_" + nom, False):
        return nom
    d = _DESSINS[k]
    for a, v in (("{HB}", "Helvetica-Bold"), ("{TB}", "Times-Bold"), ("{H}", "Helvetica")):
        d = d.replace(a, c._doc.getInternalFontName(v))
    c.beginForm(nom, 0, 0, CELL_W, CELL_H)
    c._code.append("q\n" + d + "\nQ")
    c.endForm()
    setattr(c, "_" + nom, True)
    return nom


def _billet(c, ox, oy, serie, nums, col):
    nom = _modele(c, (serie - 1) % 4)          # pique, cœur, trèfle, carreau
    c.saveState()
    c.translate(ox, oy)
    c.doForm(nom)
    _txt(c, "%06d" % serie, 27.06943, 134.6457, "Helvetica", 4.8, GRIS)
    for (m, _pl), v in zip(CARTES, nums):
        c.saveState()
        c.transform(*m)
        _txt(c, str(v), 0.8, -16.13622, POLICE_NUM, T_NUM, col, centre=True)
        c.restoreState()
    c.restoreState()


def generer_pdf(nb_cartes=None, nb_tickets=None, serie_start=1, theme="", couleur=True,
                nom_evenement="", titre_jeu="", couleur_perso="", date_lieu="",
                telephone="", page_start=1, evenement_id="", style="", motif="", **_ig):
    n_ = nb_cartes if nb_cartes is not None else nb_tickets
    n_ = max(1, int(n_ if n_ else CARTES_PAGE))
    buf = io.BytesIO()
    c = canvas.Canvas(buf, pagesize=(PAGE_W, PAGE_H), pageCompression=1)
    rng = random.Random(int(serie_start) * 100003 + 1111)
    _DEJA.clear()
    serie = int(serie_start)
    faits = 0
    try:
        no_page = max(1, int(page_start))
    except Exception:
        no_page = 1
    col_imposee = None
    if couleur and couleur_perso:
        try:
            col_imposee = colors.HexColor(couleur_perso)
        except Exception:
            col_imposee = None

    while faits < n_:
        entete = "  \u00b7  ".join(t for t in ((nom_evenement or "").strip(), (date_lieu or "").strip()) if t)
        if entete:
            c.setFillColor(NOIR); c.setFont("Helvetica-Bold", 7)
            c.drawCentredString(PAGE_W / 2.0, PAGE_H - DECAL_Y / 2.0 - 2.5, entete)
        c.setFillColor(colors.Color(0.5, 0.5, 0.5)); c.setFont("Helvetica", 6)
        c.drawRightString(PAGE_W - DECAL_X, DECAL_Y / 2.0 - 2, "page %d" % no_page)

        c.saveState()
        c.translate(DECAL_X, DECAL_Y); c.scale(ECHELLE, ECHELLE)
        for idx in range(CARTES_PAGE):
            if faits >= n_:
                break
            ox = (idx % COLS) * CELL_W
            oy = (RANGS - 1 - idx // COLS) * CELL_H
            col = (col_imposee or colors.HexColor(RAINBOW[serie % len(RAINBOW)])) if couleur else NOIR
            _billet(c, ox, oy, serie, _numeros(rng), col)
            serie += 1
            faits += 1
        c.setStrokeColor(colors.Color(0.5, 0.5, 0.5)); c.setLineWidth(0.3); c.setDash(2, 2)
        for i in range(1, COLS):
            c.line(i * CELL_W, 0, i * CELL_W, RANGS * CELL_H)
        for j in range(1, RANGS):
            c.line(0, j * CELL_H, COLS * CELL_W, j * CELL_H)
        c.restoreState()
        c.showPage()
        no_page += 1
    c.save()
    buf.seek(0)
    return buf


